// Generate files
const allArticles = generateAllArticles();
const dataDir = path.join(process.cwd(), 'data');
if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir, { recursive: true });
}

// Write full articles data
fs.writeFileSync(
  path.join(dataDir, 'articles.json'),
  JSON.stringify(allArticles, null, 2),
  'utf-8'
);

// Write lightweight index for fast listing/search
const indexData = allArticles.map(a => ({
  id: a.id,
  slug: a.slug,
  title: a.title,
  category: a.category,
  categorySlug: a.categorySlug,
  description: a.description,
  readTime: a.readTime,
  date: a.date,
  targetKeyword: a.targetKeyword
}));

fs.writeFileSync(
  path.join(dataDir, 'articles-index.json'),
  JSON.stringify(indexData, null, 2),
  'utf-8'
);

console.log(`Successfully generated ${allArticles.length} articles!`);
console.log(`Data saved to ${path.join(dataDir, 'articles.json')} and ${path.join(dataDir, 'articles-index.json')}`);
